-- migration_022_new_questions_sept2026h.sql
-- Batch 8 of new questions from "questions to add.pdf" (all Pharmacology):
--   q_mtf_opioids_immunosuppression_001                (MTF) -- knowledge box "Opioids and Immunosuppression" (+ new image images/opioid-c3-c6-hydroxyl.svg) + relevantReading (3x)
--   q_sba_opioid_choice_immunosuppression_malignancy_001 (SBA) -- shares the same knowledge box + relevantReading
--   q_mtf_opioid_induced_hypogonadism_001               (MTF) -- knowledge box "Opioids and Hormones" (+ new image images/hpg-axis-opioid-feedback.svg) + relevantReading (2x)
--   q_sba_opioid_hypogonadism_mechanism_001             (SBA) -- shares the same knowledge box + relevantReading
--   q_sba_opioid_hypogonadism_screening_panel_001       (SBA) -- shares the same knowledge box + relevantReading
--   q_sba_opioid_hypogonadism_screening_threshold_001   (SBA) -- shares the same knowledge box + relevantReading
--   q_mtf_methadone_buprenorphine_comparison_001        (MTF) -- knowledge box "Comparison of Methadone and Buprenorphine" + relevantReading (2x)
--   q_sba_buprenorphine_peripartum_analgesia_001        (SBA) -- shares the same knowledge box + relevantReading
--
-- New image assets: images/opioid-c3-c6-hydroxyl.svg, images/hpg-axis-opioid-feedback.svg
-- No new categories (Pharmacology pre-exists).
--
-- Source-PDF correction: the screening-panel question's answer line read "A — Testosterone,
-- Oestradiol, LH, FSH, prolactin", inconsistent with option A's own text ("Oestradiol, LH, FSH,
-- SHBG, prolactin") and with the vignette's 48-year-old female patient, for whom testosterone is
-- not the relevant gonadal hormone. Kept correct answer as option A (index 0) and rewrote the
-- explanation to state the correct panel without the erroneous "Testosterone" / missing "SHBG".
--
-- Post-publish edit: removed the redundant "Opioid feature / Effect" table from the
-- "Structure–Activity Relationship" section of the "Opioids and Immunosuppression" KB
-- (the image + surrounding prose already cover the same content).
--
-- Idempotent (on conflict do nothing); safe to re-run. If migration_022 was already applied
-- with the old KB content, re-running this file will NOT update existing rows (on conflict do
-- nothing) — use the UPDATE statements at the end to sync the KB edit onto already-inserted rows.

-- ===== New questions =====
insert into questions (id, type, data, status) values ('q_mtf_opioids_immunosuppression_001', 'MTF', '{"dateAdded":"2026-09-17","rotationIndex":112,"stem":"Regarding opioids and immunosuppression:","choices":["Morphine is among the most immunosuppressive opioids","Modification at the C6 hydroxyl group abolishes the immunosuppressive effect","Buprenorphine causes marked immunosuppression","Naloxone enhances immune responses","Reduced pain and effective analgesia decrease natural killer (NK) cell activity"],"correct":[true,true,false,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Opioid-induced immunosuppression depends on structural features of the drug (hydroxyl groups at C3 and C6, and receptor affinity), is reversed by receptor antagonism, and is distinct from the immune suppression caused by uncontrolled pain itself.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; Morphine retains hydroxyl groups at both C3 and C6 and has high affinity for the opioid receptor, making it among the most immunosuppressive opioids. Methadone, fentanyl, remifentanil, and pethidine also cause immunosuppression, though to a lesser degree.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Modification at the C6 position abolishes the immunosuppressive effect: opioids such as hydromorphone, oxycodone, and tramadol (which have C6 modification) show no significant immunosuppressive effect, whereas modification at C3 alone (e.g. codeine, dihydrocodeine) only reduces, rather than abolishes, the effect.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Buprenorphine has lower affinity for the opioid receptor and is associated with less immunosuppressive effect compared with high-affinity opioids like morphine; it is not classed as markedly immunosuppressive.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; Naloxone and naltrexone (opioid receptor antagonists) enhance immune responses, consistent with the concept that opioid receptor activation itself contributes to immunosuppression, which is reversed/blocked by antagonism.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; It is uncontrolled pain &mdash; not reduced pain &mdash; that decreases NK cell activity, as does the surgical stress response via the sympathetic nervous system and HPA axis. Effective analgesia reducing pain would therefore be expected to help preserve, not further decrease, NK cell activity, though the opioids used to achieve that analgesia may independently suppress immune function via their own receptor-mediated mechanisms.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioids and Immunosuppression</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Opioids modulate the immune system both directly, by binding to &mu;-opioid receptors expressed on immune cells, and indirectly, via activation of the hypothalamic-pituitary-adrenal (HPA) axis and the sympathetic nervous system (SNS). This releases glucocorticoids and noradrenaline, both of which act on leucocytes to reduce immune responsiveness.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Evidence Base</div><table style=\"margin:0\"><tr><th>Source</th><th>Finding</th></tr><tr><td>Animal</td><td>Accelerated onset of simian immunodeficiency virus (SIV) in opioid-treated animals</td></tr><tr><td>Human</td><td>Higher rates of malignancy and faster tumour spread reported in opioid users</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Structure&#8211;Activity Relationship</div><div style=\"text-align:center\"><img src=\"images/opioid-c3-c6-hydroxyl.svg\" alt=\"Morphinan skeleton showing the C3 and C6 hydroxyl positions that determine opioid immunosuppressive potential\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Opioid Antagonists and Peripheral Mechanisms</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Naloxone and naltrexone <strong>enhance</strong> immune responses, consistent with opioid receptor activation itself driving immunosuppression. Peripherally, endogenous opioids inhibit IL-2 production, while exogenous opioids inhibit IL-10 and IL-12 production by macrophages &mdash; increasing susceptibility to bacterial and viral infection &mdash; and morphine reduces bone-marrow macrophage production and T-lymphocyte proliferation.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">TLR4, Microglia, and Central Effects</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Morphine (and, to varying degrees, other opioids) acts as an agonist at Toll-like receptor 4 (TLR4), an innate immune pattern-recognition receptor normally responding to bacterial lipopolysaccharide. TLR4 is expressed on spinal cord microglia and other glial cells, and opioid-induced activation triggers a pro-inflammatory glial response (TNF-&alpha;, IL-1&beta;, IL-6, reactive oxygen species) implicated in three clinically important phenomena:</p><table style=\"margin:12px 0 0\"><tr><th>Phenomenon</th><th>Contribution of glial activation</th></tr><tr><td>Opioid tolerance</td><td>Counteracts and reduces analgesic effect over time, driving dose escalation</td></tr><tr><td>Opioid-induced hyperalgesia</td><td>Contributes to paradoxical pain sensitisation</td></tr><tr><td>Withdrawal severity</td><td>Implicated in withdrawal symptom generation</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Tumour Spread, NK Cells, and Clinical Relevance</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Natural killer (NK) cells provide immunosurveillance against malignant cells. <strong>Uncontrolled/severe pain</strong> reduces NK cell activity, as does the surgical stress response via the SNS and HPA axis &mdash; providing a theoretical rationale for effective analgesia and opioid-sparing/regional techniques in cancer surgery. This gives a theoretical basis for preferring lower-immunosuppression opioids (e.g. oxycodone, tramadol, buprenorphine) in patients with malignancy or immunocompromise, though robust outcome data remain limited; adequate analgesia itself is still important, since uncontrolled pain independently suppresses NK activity.</p></div></div>\n</div></div>","relevantReading":[{"label":"Antinociceptive and immunosuppressive effect of opioids in an acute postoperative setting: an evidence-based review","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(17)30095-1/fulltext"},{"label":"Opioids and Immunosuppression: Clinical Evidence, Mechanisms of Action, and Potential Therapies","source":"PMC","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10908329/"},{"label":"Long term harms of opioids","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-aware-clinical-use-opioids/long-term-harms-opioids"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_opioid_choice_immunosuppression_malignancy_001', 'SBA', '{"dateAdded":"2026-09-17","rotationIndex":113,"question":"A patient with active malignancy is being considered for long-term opioid analgesia. The clinical team wishes to select an opioid with the least immunosuppressive potential, given theoretical concerns about tumour immune surveillance. Which of the following opioids would be the most appropriate choice on this basis?","choices":["Morphine","Methadone","Fentanyl","Pethidine","Oxycodone"],"correct":4,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Opioid-induced immunosuppression is related to structural features of the opioid molecule &mdash; specifically the presence of hydroxyl groups at the C3 and C6 positions, alongside high mu-opioid receptor affinity. Modification at the C6 position abolishes this immunosuppressive effect, making C6-modified opioids such as oxycodone, hydromorphone, and tramadol theoretically preferable where minimising immunosuppression is a clinical priority.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Morphine retains hydroxyl groups at both C3 and C6 and has high receptor affinity, making it among the most immunosuppressive opioids &mdash; the least suitable choice here.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Methadone causes immunosuppression, though less marked than morphine, but is not the C6-modified, minimally immunosuppressive option represented by oxycodone.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Fentanyl is also associated with an immunosuppressive effect, albeit less marked than morphine, and does not carry the specific C6 modification that abolishes this effect.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Pethidine similarly causes a degree of immunosuppression, less marked than morphine but still present, and lacks the structural modification associated with abolition of the effect.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Correct.</strong> Oxycodone has modification at the C6 position, which abolishes the immunosuppressive effect seen with morphine and other unmodified opioids, making it the most appropriate choice among those listed when minimising immunosuppressive potential is a specific clinical consideration.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioids and Immunosuppression</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Opioids modulate the immune system both directly, by binding to &mu;-opioid receptors expressed on immune cells, and indirectly, via activation of the hypothalamic-pituitary-adrenal (HPA) axis and the sympathetic nervous system (SNS). This releases glucocorticoids and noradrenaline, both of which act on leucocytes to reduce immune responsiveness.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Evidence Base</div><table style=\"margin:0\"><tr><th>Source</th><th>Finding</th></tr><tr><td>Animal</td><td>Accelerated onset of simian immunodeficiency virus (SIV) in opioid-treated animals</td></tr><tr><td>Human</td><td>Higher rates of malignancy and faster tumour spread reported in opioid users</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Structure&#8211;Activity Relationship</div><div style=\"text-align:center\"><img src=\"images/opioid-c3-c6-hydroxyl.svg\" alt=\"Morphinan skeleton showing the C3 and C6 hydroxyl positions that determine opioid immunosuppressive potential\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Opioid Antagonists and Peripheral Mechanisms</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Naloxone and naltrexone <strong>enhance</strong> immune responses, consistent with opioid receptor activation itself driving immunosuppression. Peripherally, endogenous opioids inhibit IL-2 production, while exogenous opioids inhibit IL-10 and IL-12 production by macrophages &mdash; increasing susceptibility to bacterial and viral infection &mdash; and morphine reduces bone-marrow macrophage production and T-lymphocyte proliferation.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">TLR4, Microglia, and Central Effects</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Morphine (and, to varying degrees, other opioids) acts as an agonist at Toll-like receptor 4 (TLR4), an innate immune pattern-recognition receptor normally responding to bacterial lipopolysaccharide. TLR4 is expressed on spinal cord microglia and other glial cells, and opioid-induced activation triggers a pro-inflammatory glial response (TNF-&alpha;, IL-1&beta;, IL-6, reactive oxygen species) implicated in three clinically important phenomena:</p><table style=\"margin:12px 0 0\"><tr><th>Phenomenon</th><th>Contribution of glial activation</th></tr><tr><td>Opioid tolerance</td><td>Counteracts and reduces analgesic effect over time, driving dose escalation</td></tr><tr><td>Opioid-induced hyperalgesia</td><td>Contributes to paradoxical pain sensitisation</td></tr><tr><td>Withdrawal severity</td><td>Implicated in withdrawal symptom generation</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Tumour Spread, NK Cells, and Clinical Relevance</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Natural killer (NK) cells provide immunosurveillance against malignant cells. <strong>Uncontrolled/severe pain</strong> reduces NK cell activity, as does the surgical stress response via the SNS and HPA axis &mdash; providing a theoretical rationale for effective analgesia and opioid-sparing/regional techniques in cancer surgery. This gives a theoretical basis for preferring lower-immunosuppression opioids (e.g. oxycodone, tramadol, buprenorphine) in patients with malignancy or immunocompromise, though robust outcome data remain limited; adequate analgesia itself is still important, since uncontrolled pain independently suppresses NK activity.</p></div></div>\n</div></div>","relevantReading":[{"label":"Antinociceptive and immunosuppressive effect of opioids in an acute postoperative setting: an evidence-based review","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(17)30095-1/fulltext"},{"label":"Opioids and Immunosuppression: Clinical Evidence, Mechanisms of Action, and Potential Therapies","source":"PMC","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10908329/"},{"label":"Long term harms of opioids","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-aware-clinical-use-opioids/long-term-harms-opioids"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_opioid_induced_hypogonadism_001', 'MTF', '{"dateAdded":"2026-09-17","rotationIndex":114,"stem":"Regarding opioid-induced hypogonadism:","choices":["Long-term opioid use is associated with hypogonadism","Opioids act only at the level of the hypothalamus and pituitary","Prolactin is typically decreased in opioid-induced hypogonadism","Buprenorphine has less suppressive effect on the hypothalamic-pituitary-gonadal axis than morphine","Stopping opioids does not reverse the hormonal changes of opioid-induced hypogonadism"],"correct":[true,false,false,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Opioid-induced hypogonadism is a common, dose-related, and generally reversible endocrine complication of chronic opioid therapy, arising from suppression at multiple levels of the hypothalamic-pituitary-gonadal (HPG) axis.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; Over 40% of patients on long-term opioid therapy may suffer from hypogonadism, making this one of the most common endocrine complications of chronic opioid use.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. FALSE</strong> &mdash; Opioids bind to receptors at multiple levels of the HPG axis: the hypothalamus (suppressing GnRH release), the anterior pituitary (suppressing LH, and to a lesser extent FSH, release), and directly at the testes &mdash; producing a combined central and peripheral suppressive effect.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Prolactin is increased (not decreased) in opioid-induced endocrine dysfunction, alongside increased TSH; this contrasts with the broadly suppressed pattern seen with GnRH, LH, FSH, adrenal DHEA and testosterone, testicular testosterone, oestradiol/progesterone, oxytocin, and cortisol.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; Animal studies show tramadol and buprenorphine have less suppressive effect on the HPG axis compared with morphine, and buprenorphine-treated patients have been found to have normal hormonal levels, likely reflecting buprenorphine&rsquo;s partial agonist activity and lower overall opioid receptor efficacy at the relevant sites.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; The endocrine effects of opioid-induced hypogonadism are generally reversible if opioids are stopped, reflecting a functional suppressive effect on the HPG axis rather than permanent structural damage.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioids and Hormones</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Opioids bind to receptors in the hypothalamus (suppressing GnRH), the anterior pituitary (suppressing LH, and to a lesser extent FSH), and directly at the testes/ovaries. This produces a pattern of <strong>secondary (hypogonadotrophic) hypogonadism</strong> &mdash; low sex hormone with low or inappropriately normal LH and FSH &mdash; distinguishing it from primary gonadal failure, which shows high LH/FSH.</p><div style=\"text-align:center;margin-top:12px\"><img src=\"images/hpg-axis-opioid-feedback.svg\" alt=\"Hypothalamic-pituitary-gonadal axis and negative feedback loop, showing the three levels at which opioids suppress the axis\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Features and Hormonal Pattern</div><table style=\"margin:0\"><tr><th>Domain</th><th>Detail</th></tr><tr><td>Clinical features</td><td>Decreased libido, decreased muscle mass, anaemia, anxiety, depression, menstrual abnormalities (secondary amenorrhoea), osteoporosis, fractures, infertility</td></tr><tr><td>Decreased</td><td>Hypothalamic GnRH; pituitary LH (&#177; FSH); adrenal DHEA and testosterone; testicular testosterone (men); oestradiol and progesterone (women); oxytocin; cortisol</td></tr><tr><td>Increased</td><td>Prolactin; TSH</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Screening and Diagnosis Pathway</div><table style=\"margin:0\"><tr><th>Step</th><th>Action</th></tr><tr><td>Before starting treatment</td><td>Inform patients of the risk of endocrine dysfunction as a potential side effect</td></tr><tr><td>At regular follow-up</td><td>Routinely ask about symptoms suggestive of sex hormone deficiency &mdash; not a fixed dose/duration trigger</td></tr><tr><td>If symptomatic (hypogonadal symptoms)</td><td>Serum testosterone (men) / oestradiol (women), plus sex hormone-binding globulin, LH/FSH, TFTs, glucose, and U&amp;Es in both</td></tr><tr><td>If symptomatic (adrenal insufficiency)</td><td>Early morning cortisol; monitor blood pressure</td></tr><tr><td>If endocrine impairment demonstrated</td><td>Refer to an endocrinologist for advice on hormone replacement therapy</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Testing is symptom-triggered, not driven by a fixed opioid dose or duration threshold.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Differential Effects Between Opioids</div><table style=\"margin:0\"><tr><th>Opioid</th><th>Effect on the HPG axis</th></tr><tr><td>Tramadol, buprenorphine</td><td>Less suppressive effect than morphine in animal studies</td></tr><tr><td>Buprenorphine</td><td>Patients found to have normal hormonal levels, likely reflecting its partial agonist activity</td></tr><tr><td>Reversibility</td><td>Effects are generally reversible if opioids are stopped</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Long term harms of opioids","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-aware-clinical-use-opioids/long-term-harms-opioids"},{"label":"Opioid Optimisation Guidance for Pain Medicine Specialists","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/sites/fpm/files/documents/2024-11/Opioid%20Optimisation%20-%20Nov%2024_0.pdf"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_opioid_hypogonadism_mechanism_001', 'SBA', '{"dateAdded":"2026-09-17","rotationIndex":115,"question":"A 52-year-old man on long-term modified-release morphine 150mg/24 hours for chronic back pain reports reduced libido, fatigue, and low mood over the past several months. Blood tests reveal low testosterone with low LH and FSH. What is the most likely underlying mechanism?","choices":["Primary testicular failure","Opioid-induced suppression of hypothalamic GnRH release","Opioid-induced increase in sex hormone binding globulin","Autoimmune hypophysitis","Age-related decline in gonadal function alone"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">This patient&rsquo;s pattern &mdash; low testosterone with low LH and FSH &mdash; indicates a secondary (central) hypogonadism, consistent with opioid-induced suppression at the level of the hypothalamus and pituitary, rather than primary gonadal failure. Long-acting opioids at doses greater than 100mg morphine equivalent/day for more than 1 month are recognised to impair endocrine function via this mechanism.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Primary testicular failure would be expected to show low testosterone with high (not low) LH and FSH, reflecting loss of negative feedback at a normally functioning hypothalamic-pituitary axis &mdash; the opposite pattern to that described.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> Opioids act on receptors within the hypothalamus (suppressing GnRH), the anterior pituitary (suppressing LH/FSH), and the testes, producing this classic pattern of low testosterone with inappropriately low/normal LH and FSH.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> An increase in sex hormone binding globulin would primarily affect free versus total testosterone levels rather than driving genuinely low LH/FSH, and is not the recognised primary mechanism of opioid-induced hypogonadism.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Autoimmune hypophysitis is a rare cause of pituitary dysfunction, not suggested by this vignette, and considerably less likely than the well-established, common association with long-term high-dose opioid therapy described here.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> While age-related testosterone decline occurs, the specific combination of significant opioid dose/duration and the classic biochemical pattern points more directly to opioid-induced suppression as the primary driver in this vignette.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioids and Hormones</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Opioids bind to receptors in the hypothalamus (suppressing GnRH), the anterior pituitary (suppressing LH, and to a lesser extent FSH), and directly at the testes/ovaries. This produces a pattern of <strong>secondary (hypogonadotrophic) hypogonadism</strong> &mdash; low sex hormone with low or inappropriately normal LH and FSH &mdash; distinguishing it from primary gonadal failure, which shows high LH/FSH.</p><div style=\"text-align:center;margin-top:12px\"><img src=\"images/hpg-axis-opioid-feedback.svg\" alt=\"Hypothalamic-pituitary-gonadal axis and negative feedback loop, showing the three levels at which opioids suppress the axis\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Features and Hormonal Pattern</div><table style=\"margin:0\"><tr><th>Domain</th><th>Detail</th></tr><tr><td>Clinical features</td><td>Decreased libido, decreased muscle mass, anaemia, anxiety, depression, menstrual abnormalities (secondary amenorrhoea), osteoporosis, fractures, infertility</td></tr><tr><td>Decreased</td><td>Hypothalamic GnRH; pituitary LH (&#177; FSH); adrenal DHEA and testosterone; testicular testosterone (men); oestradiol and progesterone (women); oxytocin; cortisol</td></tr><tr><td>Increased</td><td>Prolactin; TSH</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Screening and Diagnosis Pathway</div><table style=\"margin:0\"><tr><th>Step</th><th>Action</th></tr><tr><td>Before starting treatment</td><td>Inform patients of the risk of endocrine dysfunction as a potential side effect</td></tr><tr><td>At regular follow-up</td><td>Routinely ask about symptoms suggestive of sex hormone deficiency &mdash; not a fixed dose/duration trigger</td></tr><tr><td>If symptomatic (hypogonadal symptoms)</td><td>Serum testosterone (men) / oestradiol (women), plus sex hormone-binding globulin, LH/FSH, TFTs, glucose, and U&amp;Es in both</td></tr><tr><td>If symptomatic (adrenal insufficiency)</td><td>Early morning cortisol; monitor blood pressure</td></tr><tr><td>If endocrine impairment demonstrated</td><td>Refer to an endocrinologist for advice on hormone replacement therapy</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Testing is symptom-triggered, not driven by a fixed opioid dose or duration threshold.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Differential Effects Between Opioids</div><table style=\"margin:0\"><tr><th>Opioid</th><th>Effect on the HPG axis</th></tr><tr><td>Tramadol, buprenorphine</td><td>Less suppressive effect than morphine in animal studies</td></tr><tr><td>Buprenorphine</td><td>Patients found to have normal hormonal levels, likely reflecting its partial agonist activity</td></tr><tr><td>Reversibility</td><td>Effects are generally reversible if opioids are stopped</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Long term harms of opioids","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-aware-clinical-use-opioids/long-term-harms-opioids"},{"label":"Opioid Optimisation Guidance for Pain Medicine Specialists","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/sites/fpm/files/documents/2024-11/Opioid%20Optimisation%20-%20Nov%2024_0.pdf"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_opioid_hypogonadism_screening_panel_001', 'SBA', '{"dateAdded":"2026-09-17","rotationIndex":116,"question":"A 48-year-old woman has been established on long-term strong opioid therapy for chronic pain for several months. As part of endocrine screening for opioid-induced hypogonadism, which panel of blood tests is most appropriate?","choices":["Oestradiol, LH, FSH, SHBG, prolactin","Testosterone, oestradiol, LH, FSH, SHBG, prolactin","Cortisol, ACTH, TSH","Full blood count and bone profile","Random growth hormone level"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Screening for opioid-induced hypogonadism should include testosterone in men, oestradiol in women, and sex hormone-binding globulin, LH/FSH, TSH, glucose, and U&amp;Es in both men and women. Testing should be offered if a patient on long-term opioid therapy is symptomatic.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> This is the appropriate panel for a female patient &mdash; oestradiol rather than testosterone, alongside LH, FSH, sex hormone-binding globulin, and prolactin (with TFTs, glucose, and U&amp;Es also indicated but not listed among these options).</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Testosterone is the sex hormone tested in men; including it here alongside oestradiol is unnecessary for a female patient, for whom oestradiol is the relevant gonadal hormone.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> While cortisol may be relevant (opioid use can be associated with reduced cortisol) and TSH is recognised to be increased with opioid use, this panel omits the core gonadal axis hormones (oestradiol, LH, FSH) central to screening for opioid-induced hypogonadism, the most common endocrine complication.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Full blood count and bone profile may be relevant as downstream markers of complications (anaemia, osteoporosis) but do not directly assess the hormonal axis itself, and are not the primary screening panel for opioid-induced hypogonadism.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Growth hormone is not the primary axis affected by opioid-induced endocrinopathy, and a single random level would have limited diagnostic value even if it were relevant.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioids and Hormones</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Opioids bind to receptors in the hypothalamus (suppressing GnRH), the anterior pituitary (suppressing LH, and to a lesser extent FSH), and directly at the testes/ovaries. This produces a pattern of <strong>secondary (hypogonadotrophic) hypogonadism</strong> &mdash; low sex hormone with low or inappropriately normal LH and FSH &mdash; distinguishing it from primary gonadal failure, which shows high LH/FSH.</p><div style=\"text-align:center;margin-top:12px\"><img src=\"images/hpg-axis-opioid-feedback.svg\" alt=\"Hypothalamic-pituitary-gonadal axis and negative feedback loop, showing the three levels at which opioids suppress the axis\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Features and Hormonal Pattern</div><table style=\"margin:0\"><tr><th>Domain</th><th>Detail</th></tr><tr><td>Clinical features</td><td>Decreased libido, decreased muscle mass, anaemia, anxiety, depression, menstrual abnormalities (secondary amenorrhoea), osteoporosis, fractures, infertility</td></tr><tr><td>Decreased</td><td>Hypothalamic GnRH; pituitary LH (&#177; FSH); adrenal DHEA and testosterone; testicular testosterone (men); oestradiol and progesterone (women); oxytocin; cortisol</td></tr><tr><td>Increased</td><td>Prolactin; TSH</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Screening and Diagnosis Pathway</div><table style=\"margin:0\"><tr><th>Step</th><th>Action</th></tr><tr><td>Before starting treatment</td><td>Inform patients of the risk of endocrine dysfunction as a potential side effect</td></tr><tr><td>At regular follow-up</td><td>Routinely ask about symptoms suggestive of sex hormone deficiency &mdash; not a fixed dose/duration trigger</td></tr><tr><td>If symptomatic (hypogonadal symptoms)</td><td>Serum testosterone (men) / oestradiol (women), plus sex hormone-binding globulin, LH/FSH, TFTs, glucose, and U&amp;Es in both</td></tr><tr><td>If symptomatic (adrenal insufficiency)</td><td>Early morning cortisol; monitor blood pressure</td></tr><tr><td>If endocrine impairment demonstrated</td><td>Refer to an endocrinologist for advice on hormone replacement therapy</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Testing is symptom-triggered, not driven by a fixed opioid dose or duration threshold.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Differential Effects Between Opioids</div><table style=\"margin:0\"><tr><th>Opioid</th><th>Effect on the HPG axis</th></tr><tr><td>Tramadol, buprenorphine</td><td>Less suppressive effect than morphine in animal studies</td></tr><tr><td>Buprenorphine</td><td>Patients found to have normal hormonal levels, likely reflecting its partial agonist activity</td></tr><tr><td>Reversibility</td><td>Effects are generally reversible if opioids are stopped</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Long term harms of opioids","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-aware-clinical-use-opioids/long-term-harms-opioids"},{"label":"Opioid Optimisation Guidance for Pain Medicine Specialists","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/sites/fpm/files/documents/2024-11/Opioid%20Optimisation%20-%20Nov%2024_0.pdf"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_opioid_hypogonadism_screening_threshold_001', 'SBA', '{"dateAdded":"2026-09-17","rotationIndex":117,"question":"At what opioid dose and duration threshold should endocrine screening for opioid-induced hypogonadism be considered?","choices":["Any dose of opioid for more than 1 week","Long-acting opioids greater than 100mg morphine equivalent/day for more than 1 month","Long-acting opioids greater than 50mg morphine equivalent/day for more than 3 months","Only after 12 months of any opioid dose","Only in patients who are symptomatic"],"correct":4,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The recognised threshold at which long-acting opioid therapy is likely to impair endocrine function is a dose greater than 100mg morphine equivalent/day, sustained for more than 1 month. However, routine testing is not recommended, and should only be offered if a patient is symptomatic.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> There is no basis for testing this early or at this low a threshold; testing is symptom-led, not time-led.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> While higher doses and longer durations increase the <em>risk</em> of endocrine dysfunction, this dose/duration figure is not itself the trigger for testing &mdash; the trigger is the presence of symptoms, which should be actively asked about at every follow-up.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Same issue as above &mdash; an arbitrary dose/duration cut-off is not the recommended basis for initiating testing.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> An elapsed-time trigger, rather than symptom-based assessment, does not reflect actual guidance, and would delay appropriate testing in symptomatic patients on shorter treatment durations while potentially over-testing asymptomatic patients at the 12-month mark.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Correct.</strong> Testing is indicated when the patient reports symptoms suggestive of sex hormone deficiency (identified through routine enquiry at follow-up), irrespective of the specific opioid dose or duration of treatment &mdash; reflecting a proactive-enquiry, symptom-triggered approach rather than a fixed dose/duration protocol.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioids and Hormones</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Opioids bind to receptors in the hypothalamus (suppressing GnRH), the anterior pituitary (suppressing LH, and to a lesser extent FSH), and directly at the testes/ovaries. This produces a pattern of <strong>secondary (hypogonadotrophic) hypogonadism</strong> &mdash; low sex hormone with low or inappropriately normal LH and FSH &mdash; distinguishing it from primary gonadal failure, which shows high LH/FSH.</p><div style=\"text-align:center;margin-top:12px\"><img src=\"images/hpg-axis-opioid-feedback.svg\" alt=\"Hypothalamic-pituitary-gonadal axis and negative feedback loop, showing the three levels at which opioids suppress the axis\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Features and Hormonal Pattern</div><table style=\"margin:0\"><tr><th>Domain</th><th>Detail</th></tr><tr><td>Clinical features</td><td>Decreased libido, decreased muscle mass, anaemia, anxiety, depression, menstrual abnormalities (secondary amenorrhoea), osteoporosis, fractures, infertility</td></tr><tr><td>Decreased</td><td>Hypothalamic GnRH; pituitary LH (&#177; FSH); adrenal DHEA and testosterone; testicular testosterone (men); oestradiol and progesterone (women); oxytocin; cortisol</td></tr><tr><td>Increased</td><td>Prolactin; TSH</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Screening and Diagnosis Pathway</div><table style=\"margin:0\"><tr><th>Step</th><th>Action</th></tr><tr><td>Before starting treatment</td><td>Inform patients of the risk of endocrine dysfunction as a potential side effect</td></tr><tr><td>At regular follow-up</td><td>Routinely ask about symptoms suggestive of sex hormone deficiency &mdash; not a fixed dose/duration trigger</td></tr><tr><td>If symptomatic (hypogonadal symptoms)</td><td>Serum testosterone (men) / oestradiol (women), plus sex hormone-binding globulin, LH/FSH, TFTs, glucose, and U&amp;Es in both</td></tr><tr><td>If symptomatic (adrenal insufficiency)</td><td>Early morning cortisol; monitor blood pressure</td></tr><tr><td>If endocrine impairment demonstrated</td><td>Refer to an endocrinologist for advice on hormone replacement therapy</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Testing is symptom-triggered, not driven by a fixed opioid dose or duration threshold.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Differential Effects Between Opioids</div><table style=\"margin:0\"><tr><th>Opioid</th><th>Effect on the HPG axis</th></tr><tr><td>Tramadol, buprenorphine</td><td>Less suppressive effect than morphine in animal studies</td></tr><tr><td>Buprenorphine</td><td>Patients found to have normal hormonal levels, likely reflecting its partial agonist activity</td></tr><tr><td>Reversibility</td><td>Effects are generally reversible if opioids are stopped</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Long term harms of opioids","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-aware-clinical-use-opioids/long-term-harms-opioids"},{"label":"Opioid Optimisation Guidance for Pain Medicine Specialists","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/sites/fpm/files/documents/2024-11/Opioid%20Optimisation%20-%20Nov%2024_0.pdf"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_methadone_buprenorphine_comparison_001', 'MTF', '{"dateAdded":"2026-09-17","rotationIndex":118,"stem":"Regarding methadone and buprenorphine:","choices":["Methadone is a mu-receptor and NMDA receptor antagonist","Buprenorphine has low intrinsic activity but high affinity at the mu-opioid receptor","Methadone is associated with less QTc prolongation than buprenorphine","Oral morphine can be used at regular doses for acute pain in patients on buprenorphine for substance misuse","Metabolism of both methadone and buprenorphine is accelerated in later pregnancy"],"correct":[false,true,false,false,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Methadone and buprenorphine differ fundamentally in receptor mechanism, cardiac safety profile, and how easily they are displaced by other opioids &mdash; distinctions that matter for both substitution therapy and acute pain management in patients established on either drug.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. FALSE</strong> &mdash; Methadone acts as a mu-opioid receptor agonist (not antagonist) alongside its NMDA receptor antagonist activity &mdash; this dual mechanism contributes to its efficacy in both opioid substitution therapy and neuropathic pain.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Buprenorphine has high affinity but low intrinsic activity (partial agonism) at the mu-opioid receptor &mdash; this combination means it binds tightly and displaces other opioids easily, while producing a submaximal effect, contributing to its ceiling effect and reduced respiratory depression risk.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; It is buprenorphine, not methadone, that is associated with less QTc prolongation. Methadone causes dose-dependent QTc prolongation, with ECG monitoring recommended at initiation and particularly at doses above 120mg/day.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; Because buprenorphine binds the mu-receptor with high affinity, displacing it requires high doses of full mu-agonists, not regular/standard doses &mdash; a clinically important consideration when managing acute pain or precipitated withdrawal in patients established on buprenorphine.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Metabolism of both methadone and buprenorphine is accelerated as pregnancy progresses, particularly in the third trimester, due to physiological and pharmacokinetic changes including increased CYP3A4 expression &mdash; both often require dose adjustment and more frequent dosing in pregnancy as a result.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Comparison of Methadone and Buprenorphine</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Methadone</strong> is a &mu;-opioid receptor agonist as well as an NMDA-receptor antagonist and monoamine reuptake inhibitor, metabolised in the liver to inactive metabolites by CYP3A4. Patients on methadone maintenance therapy should continue their usual oral dose perioperatively where possible, with additional immediate-release opioids for acute pain; if nil by mouth, rotation to an i.v. fentanyl or morphine infusion prevents withdrawal and provides analgesia.</p><p style=\"margin:10px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Buprenorphine</strong> is a partial agonist at &mu;-receptors and an antagonist at &kappa; and &delta; receptors. Its high receptor affinity and slow dissociation give it an extended duration of action, used in addiction medicine to suppress withdrawal and craving for 24&#8211;48 hours. High-dose sublingual buprenorphine can theoretically antagonise a full agonist, risking either withdrawal or analgesic failure; current practice favours continuing the patient&rsquo;s usual dose while maximising opioid-sparing adjuncts and using full agonists (at appreciably higher doses than usual) for acute pain, sometimes in a high-dependency setting.</p><p style=\"margin:10px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Naltrexone</strong> is a long-acting competitive opioid antagonist (duration ~48&#8211;72h) used to maintain abstinence. Chronic use doubles brain &mu;- and &delta;-opioid receptor density, so patients can become extremely opioid-sensitive once it is stopped; it is recommended to stop naltrexone 72h before surgery, maximising opioid-sparing strategies and considering a high-dependency setting postoperatively.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Methadone vs Buprenorphine</div><table style=\"margin:0\"><tr><th>Feature</th><th>Methadone</th><th>Buprenorphine</th></tr><tr><td>Mechanism</td><td>Mu-opioid receptor agonist + NMDA receptor antagonist</td><td>Partial mu-opioid receptor agonist &mdash; high affinity, low intrinsic activity</td></tr><tr><td>Onset / elimination</td><td>Slow onset, long elimination half-life (22&#8211;24h); once-daily dosing usually prevents withdrawal</td><td>High receptor affinity displaces other opioids easily, even at low doses; high doses of full agonists needed to displace it</td></tr><tr><td>QTc effect</td><td>Dose-dependent QTc prolongation; ECG monitoring recommended at initiation and doses &gt;120mg/day</td><td>Less QTc prolongation</td></tr><tr><td>Metabolism in pregnancy</td><td>Accelerated as pregnancy progresses (increased CYP3A4); dose adjustment/more frequent dosing often needed</td><td>Hepatic, via CYP3A4; also accelerated in pregnancy, especially third trimester; dose adjustment/more frequent dosing often needed</td></tr><tr><td>Analgesic vs withdrawal-suppression duration</td><td>Analgesic duration (4&#8211;8h) much shorter than withdrawal-suppression duration (24&#8211;48h); divided dosing (every 6&#8211;8h) may optimise peripartum analgesia</td><td>Divided dosing (3&#8211;4 times daily, every 6&#8211;8h) may similarly optimise peripartum analgesia</td></tr><tr><td>Peripartum analgesia interaction</td><td>No evidence that dose/interval affects neuraxial analgesia</td><td>Higher peri-delivery pain scores and post-Caesarean analgesic requirements with chronic use; full agonists with high intrinsic activity (sufentanil, fentanyl, hydromorphone, morphine) should be used for additional analgesia &mdash; sufentanil has higher receptor affinity than buprenorphine</td></tr><tr><td>Post-delivery management</td><td>Continue after delivery; split dosing may help</td><td>Continue after delivery; split dosing may help</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Perioperative management of opioid-tolerant patients","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(17)30056-2/fulltext"},{"label":"Management of pregnant patients with substance use disorder","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00076-9/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_buprenorphine_peripartum_analgesia_001', 'SBA', '{"dateAdded":"2026-09-17","rotationIndex":119,"question":"A pregnant woman in the third trimester, established on opioid substitution therapy, requires analgesia around the time of delivery. Which of the following statements is correct?","choices":["Methadone requires ECG monitoring","Buprenorphine has a shorter analgesic duration of action than its duration of action for suppressing withdrawal symptoms","Methadone has higher affinity for the mu-opioid receptor than buprenorphine","Both drugs should be stopped immediately after delivery to avoid neonatal complications","Sufentanil should be avoided for peripartum analgesia in patients on buprenorphine"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Methadone causes dose-dependent QTc prolongation via cardiac hERG potassium channel blockade, with ECG monitoring recommended at initiation and particularly above 120mg/day, whereas buprenorphine is associated with a comparatively lower risk of QTc prolongation.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> This accurately reflects the recognised cardiac safety profile for methadone.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> This describes methadone, not buprenorphine &mdash; methadone&rsquo;s analgesic duration (4&#8211;8 hours) is significantly shorter than its withdrawal-suppression duration (24&#8211;48 hours), which is why once-daily dosing suffices for withdrawal prevention but divided dosing is needed to maximise analgesia.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> It is buprenorphine that has the higher receptor affinity, making it harder to displace and requiring high doses of full agonists to overcome this in the acute pain setting.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Both methadone and buprenorphine should be continued after delivery, with split/divided dosing potentially beneficial in the peripartum period for both.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> The reverse is true; substances with high intrinsic activity at the mu-receptor (e.g. sufentanil, fentanyl, hydromorphone, morphine) should be used for peripartum analgesia in patients on buprenorphine, as these are more able to overcome buprenorphine’s high-affinity receptor occupancy and provide effective additional analgesia; sufentanil in particular has a higher binding affinity than buprenorphine itself.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Comparison of Methadone and Buprenorphine</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Methadone</strong> is a &mu;-opioid receptor agonist as well as an NMDA-receptor antagonist and monoamine reuptake inhibitor, metabolised in the liver to inactive metabolites by CYP3A4. Patients on methadone maintenance therapy should continue their usual oral dose perioperatively where possible, with additional immediate-release opioids for acute pain; if nil by mouth, rotation to an i.v. fentanyl or morphine infusion prevents withdrawal and provides analgesia.</p><p style=\"margin:10px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Buprenorphine</strong> is a partial agonist at &mu;-receptors and an antagonist at &kappa; and &delta; receptors. Its high receptor affinity and slow dissociation give it an extended duration of action, used in addiction medicine to suppress withdrawal and craving for 24&#8211;48 hours. High-dose sublingual buprenorphine can theoretically antagonise a full agonist, risking either withdrawal or analgesic failure; current practice favours continuing the patient&rsquo;s usual dose while maximising opioid-sparing adjuncts and using full agonists (at appreciably higher doses than usual) for acute pain, sometimes in a high-dependency setting.</p><p style=\"margin:10px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Naltrexone</strong> is a long-acting competitive opioid antagonist (duration ~48&#8211;72h) used to maintain abstinence. Chronic use doubles brain &mu;- and &delta;-opioid receptor density, so patients can become extremely opioid-sensitive once it is stopped; it is recommended to stop naltrexone 72h before surgery, maximising opioid-sparing strategies and considering a high-dependency setting postoperatively.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Methadone vs Buprenorphine</div><table style=\"margin:0\"><tr><th>Feature</th><th>Methadone</th><th>Buprenorphine</th></tr><tr><td>Mechanism</td><td>Mu-opioid receptor agonist + NMDA receptor antagonist</td><td>Partial mu-opioid receptor agonist &mdash; high affinity, low intrinsic activity</td></tr><tr><td>Onset / elimination</td><td>Slow onset, long elimination half-life (22&#8211;24h); once-daily dosing usually prevents withdrawal</td><td>High receptor affinity displaces other opioids easily, even at low doses; high doses of full agonists needed to displace it</td></tr><tr><td>QTc effect</td><td>Dose-dependent QTc prolongation; ECG monitoring recommended at initiation and doses &gt;120mg/day</td><td>Less QTc prolongation</td></tr><tr><td>Metabolism in pregnancy</td><td>Accelerated as pregnancy progresses (increased CYP3A4); dose adjustment/more frequent dosing often needed</td><td>Hepatic, via CYP3A4; also accelerated in pregnancy, especially third trimester; dose adjustment/more frequent dosing often needed</td></tr><tr><td>Analgesic vs withdrawal-suppression duration</td><td>Analgesic duration (4&#8211;8h) much shorter than withdrawal-suppression duration (24&#8211;48h); divided dosing (every 6&#8211;8h) may optimise peripartum analgesia</td><td>Divided dosing (3&#8211;4 times daily, every 6&#8211;8h) may similarly optimise peripartum analgesia</td></tr><tr><td>Peripartum analgesia interaction</td><td>No evidence that dose/interval affects neuraxial analgesia</td><td>Higher peri-delivery pain scores and post-Caesarean analgesic requirements with chronic use; full agonists with high intrinsic activity (sufentanil, fentanyl, hydromorphone, morphine) should be used for additional analgesia &mdash; sufentanil has higher receptor affinity than buprenorphine</td></tr><tr><td>Post-delivery management</td><td>Continue after delivery; split dosing may help</td><td>Continue after delivery; split dosing may help</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Perioperative management of opioid-tolerant patients","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(17)30056-2/fulltext"},{"label":"Management of pregnant patients with substance use disorder","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00076-9/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;

